<node CREATED="1298073290840" ID="Freemind_Link_1931139253" MODIFIED="1298073296402" TEXT="Definici&#xf3;n">
<node CREATED="1298071914085" ID="Freemind_Link_63620740" MODIFIED="1298071944142" TEXT="Actividad econ&#xf3;mica">
<node CREATED="1298071948528" ID="Freemind_Link_708026870" MODIFIED="1298072024805" TEXT="Actividad humana encaminada a la lucha contra la escasez, es decir la consecuci&#xf3;n de los medios, bienes y servicios escasos con los que el hombre puede satisface sus necesidades"/>
</node>
<node CREATED="1298072091180" ID="Freemind_Link_82397545" MODIFIED="1298072141929" TEXT="Organizaci&#xf3;n econ&#xf3;mica que tiene como fin la producci&#xf3;n y prestaci&#xf3;n de bienes y servicios"/>
<node CREATED="1298072171983" ID="Freemind_Link_40415753" MODIFIED="1298072207389" TEXT="La estructura, forma, tama&#xf1;o, etc var&#xed;an en el tiempo y en el espacio en funci&#xf3;n del contexto social."/>
<node CREATED="1298072233174" ID="Freemind_Link_1366410711" MODIFIED="1298072314590" TEXT="Se conjugan recursos humanos, econ&#xf3;micos, financieros y t&#xe9;cnicos lo que se desarrollan dentro de la actividad productiva, comercial  o de servicios y que en base a riesgos tratan de obtener beneficios"/>
<node CREATED="1298072433295" ID="Freemind_Link_1994982775" MODIFIED="1298072517607" TEXT="Es un ente social en el cual toda la actividad es econ&#xf3;mica o sea que tiende directamente o indirectamente al aprovechamiento fructifero de los capitales, y mediante el cual el hombre trata de satisfacer sus necesidades materiales"/>
<node CREATED="1298072529165" ID="Freemind_Link_64338597" MODIFIED="1298072547777" TEXT="Unidad econ&#xf3;mica que produce bienes y servicios"/>
<node CREATED="1298072550915" ID="Freemind_Link_1082453709" MODIFIED="1298072583867" TEXT="Unidades de producci&#xf3;n, comercializaci&#xf3;n y/o servicios que con el concurso de 3 elementos">
<node CREATED="1298072585255" ID="Freemind_Link_784052299" MODIFIED="1298072590817" TEXT="Capital"/>
<node CREATED="1298072592015" ID="Freemind_Link_350884060" MODIFIED="1298072595247" TEXT="Trabajo"/>
<node CREATED="1298072596195" ID="Freemind_Link_953439761" MODIFIED="1298072598497" TEXT="Bienes"/>
</node>
<node CREATED="1298072856202" ID="Freemind_Link_10188960" MODIFIED="1298072886764" TEXT="Tiene como objetivo obtener ganancias o lucro mediante la satisfacci&#xf3;n de necesidades"/>
</node>
<node CREATED="1298072913572" ID="Freemind_Link_672890503" MODIFIED="1298072917414" TEXT="Elementos">
<node CREATED="1298072918732" ID="Freemind_Link_867232832" MODIFIED="1298073180222" TEXT="Bienes materiales">
<icon BUILTIN="full-1"/>
<node CREATED="1298072930292" ID="Freemind_Link_1498932266" MODIFIED="1298072945348" TEXT="Bienes necesarios para el funcionamiento de la empresa"/>
<node CREATED="1298072955516" ID="Freemind_Link_770418905" MODIFIED="1298072961528" TEXT="Integrado por:">
<node CREATED="1298072962606" ID="Freemind_Link_1799496146" MODIFIED="1298072973938" TEXT="Edificios, instalaciones."/>
<node CREATED="1298072974576" ID="Freemind_Link_726555507" MODIFIED="1298072985798" TEXT="Materias primas">
<node CREATED="1298072986796" ID="Freemind_Link_1323697422" MODIFIED="1298073019708" TEXT="Recursos naturales que con ayuda del hombre deben convertirse en productos en proceso o terminados">
<node CREATED="1298073025076" ID="Freemind_Link_628868671" MODIFIED="1298073032448" TEXT="L&#xe1;minas de acero"/>
<node CREATED="1298073032976" ID="Freemind_Link_1286481565" MODIFIED="1298073042230" TEXT="Madera"/>
</node>
</node>
