<node CREATED="1298073084038" ID="Freemind_Link_80285733" MODIFIED="1298073140082" TEXT="Maquinarias que usa el hombre para la consecuci&#xf3;n o transformaci&#xf3;n de bienes.">
<node CREATED="1298073141550" ID="Freemind_Link_694496140" MODIFIED="1298073147282" TEXT="Palas mec&#xe1;nicas"/>
<node CREATED="1298073148160" ID="Freemind_Link_842857668" MODIFIED="1298073161222" TEXT="Procesadoras el&#xe9;ctricas"/>
</node>
</node>
