<node CREATED="1298073344300" ID="Freemind_Link_373883218" MODIFIED="1298073495802" TEXT="Elemento humano">
<icon BUILTIN="full-2"/>
<node CREATED="1298073353450" ID="Freemind_Link_845679369" MODIFIED="1298073386162" TEXT="Se refiere a:">
<node CREATED="1298073387100" ID="Freemind_Link_1924834835" MODIFIED="1298073396992" TEXT="Empleados"/>
<node CREATED="1298073397250" ID="Freemind_Link_146831083" MODIFIED="1298073405062" TEXT="Obreros calificados"/>
<node CREATED="1298073405840" ID="Freemind_Link_1835337486" MODIFIED="1298073412752" TEXT="Obreros no calificados"/>
<node CREATED="1298073413400" ID="Freemind_Link_1148408201" MODIFIED="1298073418012" TEXT="Directores"/>
<node CREATED="1298073420200" ID="Freemind_Link_263248128" MODIFIED="1298073425992" TEXT="Supervisores"/>
<node CREATED="1298073426520" ID="Freemind_Link_1528674033" MODIFIED="1298073431332" TEXT="T&#xe9;cnicos"/>
<node CREATED="1298073431870" ID="Freemind_Link_102097644" MODIFIED="1298073447392" TEXT="Altos ejecutivos"/>
</node>
<node CREATED="1298073455720" ID="Freemind_Link_32369689" MODIFIED="1298073469612" TEXT="Representan el elemento activo de la empresa"/>
</node>
<node CREATED="1298073501430" ID="Freemind_Link_409745541" MODIFIED="1298073509152" TEXT="Sistemas">
<icon BUILTIN="full-3"/>
<node CREATED="1298073512970" ID="Freemind_Link_645601377" MODIFIED="1298073579152" TEXT="Conjunto de procedimientos, t&#xe9;cnicas y principios, cuya utilizaci&#xf3;n permiten una mejor operatividad de la empresa, as&#xed; como los sistemas de:">
<node CREATED="1298073580770" ID="Freemind_Link_1965062147" MODIFIED="1298073588562" TEXT="Producci&#xf3;n"/>
<node CREATED="1298073588820" ID="Freemind_Link_1496019395" MODIFIED="1298073591332" TEXT="Ventas"/>
<node CREATED="1298073591700" ID="Freemind_Link_1807661394" MODIFIED="1298073596542" TEXT="Financiero"/>
<node CREATED="1298073596930" ID="Freemind_Link_1504130671" MODIFIED="1298073601342" TEXT="Organizaci&#xf3;n"/>
<node CREATED="1298073601630" ID="Freemind_Link_367539176" MODIFIED="1298073608972" TEXT="Administraci&#xf3;n"/>
<node CREATED="1298073609500" ID="Freemind_Link_709993326" MODIFIED="1298073611892" TEXT="etc."/>
</node>
</node>
</node>
<node CREATED="1298073630720" ID="Freemind_Link_902452587" MODIFIED="1298073638832" TEXT="Caracter&#xed;sticas">
<node CREATED="1298073640210" ID="Freemind_Link_464825211" MODIFIED="1298073698622" TEXT="La existencia de un patrimonio que viene a ser el conjunto de bienes econ&#xf3;micos (materiales e inmateriales) pertenecientes a una persona natural o jur&#xed;dica asociada.">
<node CREATED="1298073700420" ID="Freemind_Link_857156940" MODIFIED="1298073715222" TEXT="El patrimonio asegura la unidad de la empresa"/>
</node>
<node CREATED="1298073749810" ID="Freemind_Link_1245283709" MODIFIED="1298073776542" TEXT="Su aspecto mercantil permite producir bienes destinados al mercado"/>
<node CREATED="1298073777640" ID="Freemind_Link_93064692" MODIFIED="1298073798712" TEXT="Responde a la demanda que posee un determinado poder de compra"/>
<node CREATED="1298073830330" ID="Freemind_Link_1262607366" MODIFIED="1298073867752" TEXT="La responsabilidad es &#xfa;nica y expresamente de la empresa"/>
<node CREATED="1298073868350" ID="Freemind_Link_898824940" MODIFIED="1298073895622" TEXT="Relaci&#xf3;n econ&#xf3;mica social entre el ente econ&#xf3;mico, la sociedad y el estado"/>
<node CREATED="1298073897920" ID="Freemind_Link_840769487" MODIFIED="1298073909592" TEXT="Maximizaci&#xf3;n del beneficio"/>
</node>
<node CREATED="1298073927830" ID="Freemind_Link_1813412078" MODIFIED="1298073930582" TEXT="Fines">
<node CREATED="1298073933110" ID="Freemind_Link_713184547" MODIFIED="1298073938152" TEXT="Fin inmediato">
<node CREATED="1298073946300" ID="Freemind_Link_837326036" MODIFIED="1298074368536" TEXT="Toda empresa que produce o comercializa bienes o servicios tiene como fin llegar al mercado y enfrentarse a otras empresas tratanto de que los bienes y servicio que ofrecen tengan un logotipo de presentaci&#xf3;n, calidad."/>
</node>
<node CREATED="1298073938720" ID="Freemind_Link_767456490" MODIFIED="1298073942632" TEXT="Fin mediato">
<node CREATED="1298074080324" ID="Freemind_Link_1384547244" MODIFIED="1298074116436" TEXT="Supone analizar:">
<node CREATED="1298074117354" ID="Freemind_Link_1673133720" MODIFIED="1298074141676" TEXT="&#xbf;Qu&#xe9; se pretende lograr con la producci&#xf3;n o comercializaci&#xf3;n de bienes y/o servicios?">
<node CREATED="1298074167534" ID="Freemind_Link_1659797956" MODIFIED="1298074220506" TEXT="A nivel de la empresa privada se busca la obtenci&#xf3;n de un beneficio econ&#xf3;mico mediante la satisfacci&#xf3;n de una necesidad de orden general o social">
<node CREATED="1298074235584" ID="Freemind_Link_1132492842" MODIFIED="1298074285266" TEXT="Se refiere exclusivamente a las utilidades fij&#xe1;ndose s&#xf3;lo en la diferencia entre lo que se obtiene"/>
</node>
<node CREATED="1298074289414" ID="Freemind_Link_1938758695" MODIFIED="1298074334076" TEXT="A nivel de la empresa p&#xfa;blica, se tiene como fin satisfacer una necesidad de car&#xe1;cter general o social pudiendo obtener o no beneficios."/>
</node>
</node>
</node>
</node>
<node CREATED="1298087767061" ID="Freemind_Link_1172981271" MODIFIED="1298087774513" TEXT="Objetivos">
<node CREATED="1298087784581" ID="Freemind_Link_1193816109" MODIFIED="1298087824673" TEXT="Como ente econ&#xf3;mico tiene como objetivo fundamental">
<node CREATED="1298087826471" ID="Freemind_Link_1808235026" MODIFIED="1298087847063" TEXT="Ofrecer bienes y servicios que el ser humano necesita"/>
<node CREATED="1298087858321" ID="Freemind_Link_513544754" MODIFIED="1298087880333" TEXT="Dentro del sistema capitalista">
<node CREATED="1298087886021" ID="Freemind_Link_1256821630" MODIFIED="1298087920133" TEXT="Es la obtenci&#xf3;n de lucro o beneficio, buscando cada vez m&#xe1;s la maximizaci&#xf3;n del mismo."/>
</node>
</node>
<node CREATED="1298087926601" ID="Freemind_Link_1594344924" MODIFIED="1298087976453" TEXT="Todo negocio apunta siempre a una mayor utilidad, tratando de encontrar las mejores satisfacciones econ&#xf3;micas y sociales que el mercado ofrece"/>
</node>
<node CREATED="1298088005034" ID="Freemind_Link_1794087636" MODIFIED="1298088014616" TEXT="Sujetos de funcionamiento">
<node CREATED="1298088036574" ID="Freemind_Link_1536873641" MODIFIED="1298088062496" TEXT="Constituyen el soporte fundamental para la existencia de la misma"/>
<node CREATED="1298088066064" ID="Freemind_Link_177050062" MODIFIED="1298088069916" TEXT="Son:">
<node CREATED="1298088071084" ID="Freemind_Link_52820500" MODIFIED="1298088080066" TEXT="Accionistas o due&#xf1;os">
<node CREATED="1298088084108" ID="Freemind_Link_266917937" MODIFIED="1298088094780" TEXT="Poseedores del capital de la empresa"/>
</node>
<node CREATED="1298088095408" ID="Freemind_Link_1601108003" MODIFIED="1298088100680" TEXT="Clientes">
<node CREATED="1298088117848" ID="Freemind_Link_13346913" MODIFIED="1298088134730" TEXT="Formados por los demandantes de bienes o servicios que se ofertan"/>
</node>
<node CREATED="1298088138068" ID="Freemind_Link_1529796326" MODIFIED="1298088143400" TEXT="Proveedores">
<node CREATED="1298088144948" ID="Freemind_Link_598093652" MODIFIED="1298088208120" TEXT="Constituido por los que proveen a la empresa de productos y/o servicios, los cuales sirven para el funcionamiento o explotaci&#xf3;n del negocio."/>
</node>
<node CREATED="1298088215728" ID="Freemind_Link_1433572666" MODIFIED="1298088220640" TEXT="Estado">
<node CREATED="1298088221728" ID="Freemind_Link_985420630" MODIFIED="1298088247230" TEXT="Interviene en la empresa mediante el asesoramiento y fiscalizaci&#xf3;n.">
<node CREATED="1298088261158" ID="Freemind_Link_1208823554" MODIFIED="1298088289150" TEXT="Lo realiza mediante la obtenci&#xf3;n de impuestos, contribuciones y otros tributos a cargo de la empresa"/>
</node>
</node>
<node CREATED="1298088306368" ID="Freemind_Link_601496184" MODIFIED="1298088311660" TEXT="Trabajadores">
<node CREATED="1298088313128" ID="Freemind_Link_1491281516" MODIFIED="1298088327250" TEXT="Son la parte intelectual o manual de la empresa"/>
</node>
<node CREATED="1298088329778" ID="Freemind_Link_1315177519" MODIFIED="1298088334280" TEXT="Acreedores">
<node CREATED="1298088335988" ID="Freemind_Link_858036130" MODIFIED="1298088357620" TEXT="Los que financian a las empresas de acuerdo a la solvencia y rentabilidad de las mismas."/>
</node>
</node>
</node>
<node CREATED="1298088536035" ID="Freemind_Link_1015206117" MODIFIED="1298088545657" TEXT="Administraci&#xf3;n">
<node CREATED="1298088585335" ID="Freemind_Link_332338812" MODIFIED="1298088624817" TEXT="Las alternativas esenciales para que una empresa formada prospere se basa en una administraci&#xf3;n excelente y efectiva."/>
<node CREATED="1298088637635" ID="Freemind_Link_1493999247" MODIFIED="1298088709707" TEXT="La eficacia de la administraci&#xf3;n permite la satisfacci&#xf3;n de objetivos econ&#xf3;micos, sociales y pol&#xed;ticos los cuales redundan en una empresa de &#xe9;xito."/>
<node CREATED="1298088728215" ID="Freemind_Link_1592742315" MODIFIED="1298088851767" TEXT="La contabilidad mediante los Estados Financieros permite que la administraci&#xf3;n haga uso de criterios especiales o fundamentales, es decir, se tome decisiones para un mejor desenvolvimiento de la empresa en el mercado, ya sea maximizando la productividad, reduciendo los costos, permitiendo un mejor uso de la publicidad, etc."/>
<node CREATED="1298088871075" ID="Freemind_Link_1025851768" MODIFIED="1298088932757" TEXT="Las decisiones administrativas ser&#xe1;n formuladas en muchos casos en base a los activos y pasivos de la empresa, dando alternativas a posibles problemas que se puedan presentar."/>
</node>
<node CREATED="1298089065395" ID="Freemind_Link_41472379" MODIFIED="1298089078437" TEXT="Aspectos doctrinales de las funciones de la empresa">
<node CREATED="1298089081335" ID="Freemind_Link_1894764774" MODIFIED="1298089087767" TEXT="Funci&#xf3;n t&#xe9;cnica">
<node CREATED="1298089098265" ID="Freemind_Link_270600486" MODIFIED="1298089144087" TEXT="Mediante el empleo de conocimientos tecnol&#xf3;gicos aplicados en base a sistemas, m&#xe9;todos, procesos o servicios se genera la prosperidad o utilidad de la empresa"/>
</node>
<node CREATED="1298089183375" ID="Freemind_Link_1073383391" MODIFIED="1298089191577" TEXT="Funci&#xf3;n comercial">
<node CREATED="1298089192925" ID="Freemind_Link_1310259158" MODIFIED="1298089242757" TEXT="La sagacidad o habilidad comercial supone un profundo conocimiento del mercado y ello se consigue mediante el estudio del mismo estableciendo el potencial de la demanda y la oferta."/>
<node CREATED="1298089256785" ID="Freemind_Link_1927342592" MODIFIED="1298089262567" TEXT="Publicidad">
<node CREATED="1298089263645" ID="Freemind_Link_87434453" MODIFIED="1298089274747" TEXT="Resaltando las virtudes del producto"/>
</node>
<node CREATED="1298089291543" ID="Freemind_Link_627696349" MODIFIED="1298089296505" TEXT="Comercializaci&#xf3;n">
<node CREATED="1298089297653" ID="Freemind_Link_1495619469" MODIFIED="1298089317775" TEXT="Conociendo las v&#xed;as que conducen a los consumidores"/>
</node>
</node>
<node CREATED="1298089324943" ID="Freemind_Link_919285353" MODIFIED="1298089336325" TEXT="Funci&#xf3;n de seguridad">
<node CREATED="1298089338313" ID="Freemind_Link_642060135" MODIFIED="1298089371665" TEXT="Comprende la seguridad que se debe establecer con lo que representa los recursos de la empresa tales como:">
<node CREATED="1298089379543" ID="Freemind_Link_1738909001" MODIFIED="1298089382835" TEXT="Personas"/>
<node CREATED="1298089383423" ID="Freemind_Link_1746535936" MODIFIED="1298089389365" TEXT="Maquinarias"/>
<node CREATED="1298089389623" ID="Freemind_Link_1681088115" MODIFIED="1298089395865" TEXT="Instalaciones"/>
<node CREATED="1298089396113" ID="Freemind_Link_243496934" MODIFIED="1298089402565" TEXT="Mercader&#xed;as"/>
<node CREATED="1298089402843" ID="Freemind_Link_475441758" MODIFIED="1298089410875" TEXT="Materias primas"/>
<node CREATED="1298089411683" ID="Freemind_Link_1568214379" MODIFIED="1298089415375" TEXT="etc."/>
</node>
</node>
<node CREATED="1298089460403" ID="Freemind_Link_1957784910" MODIFIED="1298089467705" TEXT="Funci&#xf3;n financiera">
<node CREATED="1298089470403" ID="Freemind_Link_1263271396" MODIFIED="1298089556685" TEXT="Mediante esta funci&#xf3;n se dispondr&#xe1; de forma espec&#xed;fica de los capitales dirigidos a la operatividad o reinversi&#xf3;n en la empresa, como los gastos generales, compra de bienes y servicios, etc."/>
</node>
<node CREATED="1298089574123" ID="Freemind_Link_1333916246" MODIFIED="1298089579595" TEXT="Funci&#xf3;n contable">
<node CREATED="1298089581223" ID="Freemind_Link_1006139051" MODIFIED="1298089610855" TEXT="Es un medio importante de direcci&#xf3;n administrativa mediante el registro de las operaciones contables en libros especiales."/>
</node>
<node CREATED="1298089641313" ID="Freemind_Link_326281970" MODIFIED="1298089647585" TEXT="Funci&#xf3;n administrativa">
<node CREATED="1298089655683" ID="Freemind_Link_297048555" MODIFIED="1298089691935" TEXT="Es la funci&#xf3;n m&#xe1;s importante porque permite proveer, organizar, dirigir, planificar, coordinar, controlar, etc."/>
<node CREATED="1298089694423" ID="Freemind_Link_1015596923" MODIFIED="1298089715675" TEXT="Se manifiesta primordialmente en los trabajos de oficina"/>
</node>
</node>
<node CREATED="1298089735533" ID="Freemind_Link_1375967390" MODIFIED="1298089744455" TEXT="Clases de empresas">
<node CREATED="1298089755913" ID="Freemind_Link_1154236113" MODIFIED="1298090256505" TEXT="Empresas industriales">
<icon BUILTIN="full-1"/>
<node CREATED="1298089766083" ID="Freemind_Link_1114277454" MODIFIED="1298089803645" TEXT="Son las que se forman con la finalidad de transformar los recursos naturales o intermediarios en bienes finales que satisfagan las necesidad del hombre."/>
</node>
<node CREATED="1298089844483" ID="Freemind_Link_1467270151" MODIFIED="1298090259115" TEXT="Empresas comerciales">
<icon BUILTIN="full-2"/>
<node CREATED="1298089856873" ID="Freemind_Link_1537647522" MODIFIED="1298089913595" TEXT="Son aquellas que compran bienes para luego ofertarlos a otras empresas o a un consumidor intermedio o final."/>
</node>
<node CREATED="1298090306404" ID="Freemind_Link_1838880483" MODIFIED="1298090416456" TEXT="Empresas extractivas">
<icon BUILTIN="full-3"/>
<node CREATED="1298090326564" ID="Freemind_Link_496589337" MODIFIED="1298090371476" TEXT="Son aquellas que extraen o explotan los recursos que brinda la naturaleza para luego ser comercializados o transformados, tales como:">
<node CREATED="1298090372924" ID="Freemind_Link_202240846" MODIFIED="1298090376156" TEXT="Minerales"/>
<node CREATED="1298090376424" ID="Freemind_Link_1545235926" MODIFIED="1298090382586" TEXT="&#xc1;rboles"/>
<node CREATED="1298090382914" ID="Freemind_Link_267853002" MODIFIED="1298090387246" TEXT="Peces"/>
<node CREATED="1298090388164" ID="Freemind_Link_1682008917" MODIFIED="1298090390946" TEXT="etc."/>
</node>
</node>
<node CREATED="1298089925103" ID="Freemind_Link_1447154242" MODIFIED="1298090419186" TEXT="Empresas financieras">
<icon BUILTIN="full-4"/>
<node CREATED="1298089937083" ID="Freemind_Link_904186592" MODIFIED="1298089996975" TEXT="Son las empresas que facilitan las operaciones mercantiles mediante cr&#xe9;ditos, o relaciones financieras tales como:">
<node CREATED="1298090001593" ID="Freemind_Link_1082692042" MODIFIED="1298090008475" TEXT="Cuentas corrientes"/>
<node CREATED="1298090008763" ID="Freemind_Link_1121292768" MODIFIED="1298090013425" TEXT="Ahorros"/>
<node CREATED="1298090013683" ID="Freemind_Link_1302795984" MODIFIED="1298090018595" TEXT="Cheques"/>
<node CREATED="1298090018993" ID="Freemind_Link_1416563509" MODIFIED="1298090024355" TEXT="Giros bancarios"/>
<node CREATED="1298090024643" ID="Freemind_Link_1353648740" MODIFIED="1298090034185" TEXT="Tarjetas de cr&#xe9;dito"/>
<node CREATED="1298090036393" ID="Freemind_Link_440428677" MODIFIED="1298090040945" TEXT="Pagar&#xe9;s"/>
</node>
